            /**
             * Hostname of the Machine. Defaults to the Machine ID. Also added to /etc/hosts with the
             * Machine's 6PN address
             */
            hostname?: string;
            /**
             * Fully qualified domain name added to /etc/hosts for `hostname`
             */
